package main
import("strings";"strconv")
var _=strings.Compare
var _=strconv.Itoa
func solve(x map[string]any) any {p:=x["pointer"].(string);var cur any=x["doc"];if p==""{return cur};for _,key:=range strings.Split(strings.TrimPrefix(p,"/"),"/"){switch node:=cur.(type){case map[string]any:cur=node[key];case []any:n,err:=strconv.Atoi(key);if err!=nil||n<0||n>=len(node){return nil};cur=node[n];default:return nil}};return cur}

public.main.go:
package main
import("encoding/json";"os";"fmt")
func main(){var inputs []map[string]any;if e:=json.Unmarshal([]byte(os.Args[1]),&inputs);e!=nil{panic(e)};out:=[]any{};for _,x:=range inputs{out=append(out,solve(x))};b,e:=json.Marshal(out);if e!=nil{panic(e)};fmt.Println(string(b))}

